from dataclasses import dataclass
from pricing import rules, subtotal

@dataclass(frozen=True)
class Line:
    sku: str
    unit_cents: int
    quantity: int

def quote(lines, region, member=False):
    if region not in {'domestic', 'international'}:
        raise ValueError('region')
    amount, count = subtotal(lines)
    policy = rules()
    discount = amount // 10 if member and amount >= 5000 else 0
    discounted_amount = amount - discount
    if not count:
        shipping = 0
    elif region == 'international':
        shipping = policy['international_cents']
    elif discounted_amount >= policy['free_threshold']:
        shipping = 0
    else:
        shipping = policy['domestic_cents']
    return {
        'subtotal_cents': amount,
        'discount_cents': discount,
        'shipping_cents': shipping,
        'total_cents': discounted_amount + shipping,
    }
